// Derived once at module load so per-request cost is independent of rate.

/** Ascending non-conformity scores s_i = 1 - P_hat(true_i) for the p-value. */
export const CALIBRATION_SORTED_TRUE_SCORES: readonly number[] = CALIBRATION_SCORES.map(
  (r) => 1 - r.phat[r.trueIndex],
).sort((x, y) => x - y);

/** One-vs-rest (score, outcome) pairs per category, for Venn-Abers. */
export const CALIBRATION_ONE_VS_REST: readonly (readonly { s: number; z: 0 | 1 }[])[] =
  ["Direct Answer","Needs Clarification","Escalate — Outside Model's Reliable Scope"].map((_, k) =>
    CALIBRATION_SCORES.map((r) => ({ s: r.phat[k], z: (r.trueIndex === k ? 1 : 0) as 0 | 1 })),
  );
